package br.com.brindespro.security;
import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.http.HttpMethod;import org.springframework.security.authentication.*;import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.core.userdetails.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.csrf.CookieCsrfTokenRepository;import org.springframework.security.web.context.HttpSessionSecurityContextRepository;import org.springframework.security.web.context.SecurityContextRepository;import org.springframework.web.cors.*;import java.util.*;
@Configuration public class SecurityConfig { @Value("${app.frontend-origin}") private String frontendOrigin;
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService users(AdminUserRepository repo){return email->{AdminUser user=repo.findByEmail(email).filter(u->u.active).orElseThrow(()->new UsernameNotFoundException("Usuário não encontrado"));return User.withUsername(user.email).password(user.passwordHash).roles("ADMIN").build();};}
 @Bean AuthenticationManager authenticationManager(AuthenticationConfiguration config)throws Exception{return config.getAuthenticationManager();}
 @Bean SecurityContextRepository contextRepository(){return new HttpSessionSecurityContextRepository();}
 @Bean CorsConfigurationSource cors(){CorsConfiguration config=new CorsConfiguration();config.setAllowedOrigins(List.of(frontendOrigin));config.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));config.setAllowedHeaders(List.of("Content-Type","X-XSRF-TOKEN"));config.setAllowCredentials(true);UrlBasedCorsConfigurationSource source=new UrlBasedCorsConfigurationSource();source.registerCorsConfiguration("/**",config);return source;}
 @Bean SecurityFilterChain filterChain(HttpSecurity http,SecurityContextRepository repository)throws Exception{return http.cors(c->{}).csrf(c->c.csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse())).securityContext(c->c.securityContextRepository(repository)).authorizeHttpRequests(a->a.requestMatchers("/api/admin/**").authenticated().requestMatchers(HttpMethod.GET,"/api/quotes/**").authenticated().requestMatchers(HttpMethod.GET,"/api/files/**").authenticated().requestMatchers("/api/auth/me").authenticated().anyRequest().permitAll()).formLogin(f->f.disable()).httpBasic(b->b.disable()).build();}
}
